<div class="section-head"><div><p class="eyebrow">ADMINISTRATION</p><h1>Cuisines &amp; tags</h1></div></div>
<div class="taxonomy-columns"><?php foreach(['cuisine'=>$cuisines,'tag'=>$tags] as $type=>$items):?><section class="panel"><h2><?=ucfirst($type)?>s</h2><form method="post" action="/admin/taxonomy" class="inline taxonomy-add"><?=csrf()?><input type="hidden" name="type" value="<?=$type?>"><input name="name" minlength="2" maxlength="80" required placeholder="Add <?=e($type)?>"><button class="small">Add</button></form><div class="taxonomy-list"><?php foreach($items as $item):?><form method="post" action="/admin/taxonomy/<?=$type?>/<?=$item['id']?>" class="taxonomy-row"><?=csrf()?><input name="name" value="<?=e($item['name'])?>" minlength="2" maxlength="80" required><label class="toggle compact"><input type="checkbox" name="is_active" value="1" <?=$item['is_active']?'checked':''?>><span></span><small>Active</small></label><button class="small secondary">Save</button></form><?php endforeach?></div></section><?php endforeach?></div>
